package io.github.toolazytoname.xiaohei;
public final class RootDestructiveDenialPolicyTest {public static void main(String[] x){int destructive=0,path=0,secret=0;String[] ds={"rm -rf /","dd if=/dev/zero","mkfs.ext4","fastboot flash boot","git reset --hard","iptables -F"};for(String c:ds){expect(RootDestructiveDenialPolicy.Decision.DENY_DESTRUCTIVE,c,"","read");destructive++;}String[] ps={"/","/data/user/0","/system","/vendor","../secret","*.db"};for(String p:ps){expect(RootDestructiveDenialPolicy.Decision.DENY_BROAD_PATH,"",p,"read");path++;}String[] ss={"password dump","otp fetch","token export","cookie copy","payment data","keychain list"};for(String c:ss){expect(RootDestructiveDenialPolicy.Decision.DENY_SECRET,c,"","read");secret++;}expect(RootDestructiveDenialPolicy.Decision.DENY_SECRET,"","","上传凭据");expect(RootDestructiveDenialPolicy.Decision.DENY_UNKNOWN,"status","","observe");System.out.println("PASS RootDestructiveDenialPolicyTest destructive=6 broad_path=6 secret=7 unknown=1 execution_paths=0");}private static void expect(RootDestructiveDenialPolicy.Decision e,String c,String p,String i){if(RootDestructiveDenialPolicy.assess(c,p,i)!=e)throw new AssertionError(c+p+i);}}
